using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Newtonsoft.Json.Linq;
public static class VfxV6Export {
 public static object Run(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");const string root="아트/이펙트/전투-v6";var report=new List<object>();foreach(var part in JArray.Parse(File.ReadAllText(root+"/manifest.json"))){string id=(string)part["id"];int w=(int)part["width"],h=(int)part["height"];var rgba=File.ReadAllBytes(root+"/layers/"+id+"/composite.rgba");var pixels=new Color32[w*h/4];int nonzero=0;for(int y=0;y<h/2;y++)for(int x=0;x<w/2;x++){int r=0,g=0,b=0,a=0;for(int j=0;j<2;j++)for(int i=0;i<2;i++){// Aseprite rows run from the top; Unity rows run from the bottom.
 int at=((h-1-(2*y+j))*w+2*x+i)*4;int alpha=rgba[at+3];r+=rgba[at]*alpha;g+=rgba[at+1]*alpha;b+=rgba[at+2]*alpha;a+=alpha;}pixels[y*w/2+x]=a>0?new Color32((byte)((r+a/2)/a),(byte)((g+a/2)/a),(byte)((b+a/2)/a),(byte)((a+2)/4)):new Color32();if(a>0)nonzero++;}var t=new Texture2D(w/2,h/2,TextureFormat.RGBA32,false);t.SetPixels32(pixels);t.Apply();var png=t.EncodeToPNG();File.WriteAllBytes(root+"/runtime-PNG/"+id+".png",png);File.WriteAllBytes("Assets/Art/EffectsV6/"+id+".png",png);UnityEngine.Object.DestroyImmediate(t);report.Add(new{id,width=w/2,height=h/2,alphaWeightedDownsample=true,nonzeroPixels=nonzero});}AssetDatabase.Refresh();File.WriteAllText(root+"/export-validation.json",Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));return report;}
}
